<?php
require dirname(__DIR__).'/public/database.php';require dirname(__DIR__).'/public/schema.php';
$cfg=appConfig();if(!str_starts_with($cfg['db_name']??'','itu_test_')||!in_array($cfg['db_host']??'',['127.0.0.1','localhost'],true))exit(2);
$pdo=appDatabase();appSchema($pdo);$_SESSION=[];$users=[];$pass=0;
set_error_handler(function($s,$m,$f,$l){if(error_reporting()&$s)throw new ErrorException($m,0,$s,$f,$l);});
function expect($x,$msg){if(!$x)throw new RuntimeException($msg);}
function refuses($f){try{$f();}catch(RuntimeException $e){if($e instanceof PDOException)throw $e;return;}throw new RuntimeException('Expected rejection');}
function test($n,$f){global $pass;$f();$pass++;echo "PASS $n\n";}
foreach([1,2] as $x){opsExec($pdo,'INSERT INTO users(phone,password,biz_name,biz_category,location) VALUES(?,?,?,?,?)',['rev-'.bin2hex(random_bytes(6)),password_hash('Test',PASSWORD_DEFAULT),'Demo','cafe','Тараз']);$users[]=(int)$pdo->lastInsertId();}
[$u,$other]=$users;$owner=['id'=>$u,'biz_name'=>'Demo','location'=>'Тараз'];
try{
    $setup=assistantDemoSetup($pdo,$u);
    test('demo setup is idempotent and tenant isolated',function()use($pdo,$u,$other,$setup){expect(assistantDemoSetup($pdo,$u)===$setup,'setup duplicated');expect(count(opsCatalog($pdo,$u))===4&&count(opsCatalog($pdo,$other))===0,'catalog scope');expect(count(reviewExamples($pdo,$u)['reviews'])===3,'review duplicate');foreach(opsCatalog($pdo,$u) as $r)expect($r['details']['data_mode']==='demo','real data flag');});
    $review=reviewExamples($pdo,$u)['reviews'][0];$model=fn()=>['topic'=>'Ожидание','summary'=>'Гость сообщает о задержке.','reply'=>'Спасибо за отзыв. Проверим причину задержки.','decision'=>'Проверить время ожидания и расписание.','sentiment'=>'negative','priority'=>'normal'];
    test('review analysis, edited reply and task never imply external publication',function()use($pdo,$u,$other,$review,$model){refuses(fn()=>reviewAnalyze($pdo,$other,$review['id'],[],$model));reviewAnalyze($pdo,$u,$review['id'],[],$model);$a=reviewAction($pdo,$u,$review['id'],'reply',['text'=>'Спасибо, уточним время визита.']);expect($a['external_delivery']===false&&$a['data']['state']==='demo_answered','false external success');$a=reviewAction($pdo,$u,$review['id'],'task',[]);$b=reviewAction($pdo,$u,$review['id'],'task',[]);expect($a['data']['task_id']===$b['data']['task_id'],'duplicate task');refuses(fn()=>reviewAnalyze($pdo,$u,$review['id'],[],fn()=>['reply'=>'partial']));});
    test('customer field extraction accepts evidence, rejects model-invented contact',function(){ $f=botCustomerFields('Меня зовут Дана, телефон +7 000 000 00 01, заберу в 18:30.');expect($f['client']==='Дана'&&$f['phone']==='70000000001'&&$f['pickup_at']==='в 18:30','inline extraction');$f=botCustomerFields('Мне нужен кофе','',['client'=>'Айжан','phone'=>'79999999999','pickup_at'=>'18:00']);expect(!$f,'invented fields');expect(!botCustomerFields('Подтверждаю','name'),'confirmation became name');});
    opsSaveSettings($pdo,$u,['bot_mode'=>'free']);$chat='90022001';
    test('all checkout details in one message skip redundant questions and save once',function()use($pdo,$u,$owner,$chat){$r=opsBotHandle($pdo,$owner,$chat,'Заказ: латте 2; круассан 1',[]);expect(str_contains($r,'3 100,00')&&str_contains($r,'имя'),'order start');opsBotHandle($pdo,$owner,$chat,'Подтверждаю',[]);expect(!opsOne($pdo,'SELECT id FROM ops_orders WHERE user_id=?',[$u]),'early confirmation saved');$r=opsBotHandle($pdo,$owner,$chat,'Меня зовут Дана, телефон +7 000 000 00 01, заберу в 18:30.',[]);expect(str_contains($r,'Дана')&&str_contains($r,'70000000001')&&str_contains($r,'Подтверждаю'),'summary not filled');opsBotHandle($pdo,$owner,$chat,'Подтверждаю',[]);opsBotHandle($pdo,$owner,$chat,'Подтверждаю',[]);$rows=opsAll($pdo,'SELECT payload,is_demo FROM ops_orders WHERE user_id=?',[$u]);expect(count($rows)===1&&$rows[0]['is_demo']==1,'duplicate or live');expect(json_decode($rows[0]['payload'],true)['client']==='Дана','saved name');});
    test('booking collects name/contact and guards an occupied slot',function()use($pdo,$u,$owner){$chat='90022002';opsBotHandle($pdo,$owner,$chat,'Записаться',[]);opsBotHandle($pdo,$owner,$chat,'2',[]);opsBotHandle($pdo,$owner,$chat,'1',[]);$date=(new DateTimeImmutable('tomorrow',new DateTimeZone('Asia/Qyzylorda')))->format('Y-m-d');opsBotHandle($pdo,$owner,$chat,$date,[]);$r=opsBotHandle($pdo,$owner,$chat,'15:00',[]);expect(str_contains($r,'имя'),'booking missing contact step');$r=opsBotHandle($pdo,$owner,$chat,'Меня зовут Дана, телефон +7 000 000 00 01.',[]);expect(str_contains($r,'Подтверждаю')&&!str_contains($r,'Когда удобно'),'booking summary');$pending=opsChat($pdo,$u,$chat)['pending'];opsBotHandle($pdo,$owner,$chat,'Подтверждаю',[]);$a=opsOne($pdo,'SELECT * FROM ops_appointments WHERE user_id=?',[$u]);expect($a['status']==='confirmed'&&json_decode($a['payload'],true)['client']==='Дана','booking not filled');refuses(fn()=>opsCheckSlot($pdo,$u,$pending['data']['resource_id'],$pending['data']['item_id'],$pending['data']['starts_at']));expect(opsReport($pdo,$u,$date,$date)['completed_visits']===0,'demo leaked into report');});
    test('natural booking commands reach the intent parser, not the price shortcut',function()use($pdo,$u){$catalog=publicCatalogData($pdo,$u);expect(botQuickAnswer($pdo,$u,'Запиши на консультацию завтра в 15:00',$catalog)===null,'booking treated as question');expect(botLocalIntent($catalog,'Запиши на консультацию')['intent']==='booking','booking not detected');});
    test('2GIS connector encrypts keys, isolates tenants and reports only actual statistics',function()use($pdo,$u,$other,$cfg){$mock=fn()=>['meta'=>['code'=>200],'result'=>['items'=>[['id'=>'70000000000001_hash','name'=>'Fixture company','address_name'=>'Fixture address','reviews'=>['general_rating'=>4.7,'general_review_count'=>23]],['id'=>'70000000000002','name'=>'Without rating']]]];gisConnect($pdo,$u,'fixture-key-1234567890',$cfg,$mock);$stored=opsOne($pdo,'SELECT key_box FROM gis_connections WHERE user_id=?',[$u])['key_box'];expect(!str_contains($stored,'fixture-key'),'plain key');$r=gisSearch($pdo,$u,'Тараз кафе',$cfg,$mock);expect($r['items'][0]['rating']===4.7&&$r['items'][1]['rating']===null,'invented rating');expect(!gisStatus($pdo,$other)['connected'],'foreign status');refuses(fn()=>gisSearch($pdo,$other,'Тараз кафе',$cfg,$mock));refuses(fn()=>gisConnect($pdo,$u,'fixture-key-1234567890',$cfg,fn()=>['meta'=>['code'=>403]]));});
    test('manual 2GIS reviews retain provenance, reject unsafe links, and stay drafts',function()use($pdo,$u,$model){$input=['url'=>'https://2gis.kz/taraz/firm/70000000000001','text'=>'Проверочный текст, введённый вручную.','rating'=>3];$a=reviewManual($pdo,$u,$input);expect(reviewManual($pdo,$u,$input)['id']===$a['id'],'duplicate import');reviewAnalyze($pdo,$u,$a['id'],[],$model);$r=reviewAction($pdo,$u,$a['id'],'reply',['text'=>'Спасибо за мнение.']);expect($r['data']['state']==='draft_ready'&&!$r['data']['is_demo']&&!$r['external_delivery'],'manual review mislabelled');foreach(['javascript:alert(1)','https://2gis.kz.attacker.invalid/firm/12345','https://user:pass@2gis.kz/firm/12345'] as $url)refuses(fn()=>reviewManual($pdo,$u,array_merge($input,['url'=>$url])));});
    test('natural booking fills date, service, resource and contact without model dependency',function()use($pdo,$u,$owner){$r=opsBotHandle($pdo,$owner,'90022003','Забронируй стол завтра в 18:00. Меня зовут Дана, телефон +7 000 000 00 01.',[]);expect(str_contains($r,'Подтверждаю')&&str_contains($r,'18:00')&&str_contains($r,'Дана'),'natural booking failed');opsBotHandle($pdo,$owner,'90022003','Подтверждаю',[]);$n=(int)opsOne($pdo,'SELECT COUNT(*) n FROM ops_appointments WHERE user_id=?',[$u])['n'];opsBotHandle($pdo,$owner,'90022003','Подтверждаю',[]);expect((int)opsOne($pdo,'SELECT COUNT(*) n FROM ops_appointments WHERE user_id=?',[$u])['n']===$n,'repeated confirmation');});
    echo "RESULT $pass review/checkout scenarios passed; no external calls.\n";
}finally{foreach($users as $id){foreach(['gis_connections','ops_outbox','ops_orders','ops_chats','ops_appointments','ops_resources','ops_settings','ops_audit','aulieata_records','aulieata_catalog_details','business_catalog'] as $table)opsExec($pdo,'DELETE FROM '.$table.' WHERE user_id=?',[$id]);opsExec($pdo,'DELETE FROM users WHERE id=?',[$id]);}}
